CREATE TABLE IF NOT EXISTS public.report_template_keys (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), template_id UUID NOT NULL REFERENCES public.report_templates(id) ON DELETE CASCADE, key_name TEXT NOT NULL, display_label TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'general', field_type TEXT NOT NULL DEFAULT 'text', default_value TEXT NOT NULL DEFAULT '', is_required BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_report_template_keys_tmpl_key UNIQUE (template_id, key_name));
CREATE INDEX IF NOT EXISTS idx_report_template_keys_template_id ON public.report_template_keys(template_id);
ALTER TABLE public.report_template_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY "template_keys_select" ON public.report_template_keys FOR SELECT TO authenticated USING (true);
CREATE POLICY "template_keys_insert" ON public.report_template_keys FOR INSERT TO authenticated WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "template_keys_update" ON public.report_template_keys FOR UPDATE TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY "template_keys_delete" ON public.report_template_keys FOR DELETE TO authenticated USING (auth.uid() IS NOT NULL);
